CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE game_users(id uuid PRIMARY KEY, login text NOT NULL UNIQUE, display_name text NOT NULL, password_hash text NOT NULL, roles text[] NOT NULL DEFAULT '{PLAYER}', mfa_secret text, mfa_pending text, mfa_counter bigint NOT NULL DEFAULT -1, created_at timestamptz NOT NULL DEFAULT now(), CHECK(roles <@ ARRAY['PLAYER','MODERATOR','CONTENT_EDITOR','ADMIN','SUPER_ADMIN']::text[]));
CREATE TABLE user_sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES game_users(id),csrf text NOT NULL,expires_at timestamptz NOT NULL,mfa_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user ON user_sessions(user_id);
CREATE TABLE player_states(user_id uuid PRIMARY KEY REFERENCES game_users(id),state jsonb NOT NULL,version bigint NOT NULL DEFAULT 1);
CREATE TABLE game_wallets(user_id uuid PRIMARY KEY REFERENCES game_users(id),coins bigint NOT NULL DEFAULT 150 CHECK(coins>=0));
CREATE TABLE coin_ledger(id bigserial PRIMARY KEY,user_id uuid NOT NULL REFERENCES game_users(id),delta bigint NOT NULL,balance bigint NOT NULL CHECK(balance>=0),source_type text NOT NULL,source_ref text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,source_type,source_ref));
CREATE TABLE admin_audit_events(id bigserial PRIMARY KEY,actor_id uuid REFERENCES game_users(id),action text NOT NULL,target text,reason text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION prevent_mutation() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'append-only record'; END$$;
CREATE TRIGGER immutable_ledger BEFORE UPDATE OR DELETE ON coin_ledger FOR EACH ROW EXECUTE FUNCTION prevent_mutation();
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON admin_audit_events FOR EACH ROW EXECUTE FUNCTION prevent_mutation();
CREATE TABLE catalog_current(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),version integer NOT NULL,payload jsonb NOT NULL);
CREATE TABLE catalog_publications(version integer PRIMARY KEY,payload jsonb NOT NULL,actor_id uuid REFERENCES game_users(id),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE catalog_drafts(id uuid PRIMARY KEY,kind text NOT NULL,stable_id text NOT NULL,payload jsonb NOT NULL,version integer NOT NULL DEFAULT 1,status text NOT NULL DEFAULT 'draft',author uuid REFERENCES game_users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sanctions(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES game_users(id),scope text NOT NULL CHECK(scope IN ('CHAT','ACCOUNT')),reason text NOT NULL,ends_at timestamptz NOT NULL,revoked_at timestamptz,actor_id uuid REFERENCES game_users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE chat_messages(id bigserial PRIMARY KEY,room text NOT NULL,user_id uuid NOT NULL REFERENCES game_users(id),request_id text NOT NULL,body text NOT NULL,status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,request_id));
CREATE INDEX messages_room ON chat_messages(room,id DESC);
CREATE TABLE chat_reports(id bigserial PRIMARY KEY,message_id bigint NOT NULL REFERENCES chat_messages(id),reporter uuid NOT NULL REFERENCES game_users(id),reason text NOT NULL,status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(message_id,reporter));
CREATE TABLE chat_appeals(id bigserial PRIMARY KEY,user_id uuid NOT NULL REFERENCES game_users(id),sanction_id uuid NOT NULL REFERENCES sanctions(id),body text NOT NULL,status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE virtual_projects(id text PRIMARY KEY,total bigint NOT NULL DEFAULT 0,goal bigint NOT NULL DEFAULT 1000);
INSERT INTO virtual_projects(id) VALUES ('noel');
CREATE TABLE operation_receipts(user_id uuid NOT NULL REFERENCES game_users(id),key text NOT NULL,kind text NOT NULL,payload_hash text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,key));
CREATE TABLE demo_imports(user_id uuid PRIMARY KEY REFERENCES game_users(id),fingerprint text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE seat_leases(seat_id text PRIMARY KEY,user_id uuid NOT NULL UNIQUE REFERENCES game_users(id),expires_at timestamptz NOT NULL);
CREATE TABLE live_events(session_id uuid NOT NULL,event_id text NOT NULL,viewer_hash text NOT NULL,status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(session_id,event_id));
CREATE TABLE live_sessions(id uuid PRIMARY KEY,settings jsonb NOT NULL,running boolean NOT NULL DEFAULT false,created_by uuid NOT NULL REFERENCES game_users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE settings(key text PRIMARY KEY,value jsonb NOT NULL);
INSERT INTO settings(key,value) VALUES ('ambient','{"targetVisualActors":16,"ambientMax":18,"renderCap":32,"reconcilePeriodSeconds":5}'::jsonb),('chat','{"enabled":true,"minIntervalMs":3000,"maxPer30Seconds":5}'::jsonb);
